  "stack-list": {
   "starter": "class Stack:\n    \"\"\"Стек (LIFO — Last In, First Out) на списке Python — так делали на парах.\n    Вершина стека — КОНЕЦ списка: append и pop в конце работают за O(1).\n    Сам стек занимает O(n).\"\"\"\n\n    def __init__(self):\n        self.data = []\n\n    def add(self, val):\n        \"\"\"Положить элемент на вершину (push).\n        Время O(1) амортизированно: list.append пишет в конец, изредка список\n        расширяется (копирование O(n)), но в среднем O(1). Память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def remove(self):\n        \"\"\"Снять элемент с вершины и вернуть его (pop).\n        Время O(1): удаление последнего элемента ничего не сдвигает. Память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def peek(self):\n        \"\"\"Посмотреть верхний элемент, не удаляя его. Время O(1), память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def is_empty(self):\n        return len(self.data) == 0\n\n    def __len__(self):\n        return len(self.data)\n\n    def __str__(self):\n        return \"bottom -> \" + str(self.data) + \" <- top\"\n\nif __name__ == \"__main__\":\n    # «Запустить» выполняет этот блок. «Проверить» запускает скрытые тесты.\n    s = Stack()\n    for x in [1, 2, 3]:\n        s.add(x)\n    print(s.peek())     # ожидается 3\n    print(s.remove())   # ожидается 3\n    print(s)            # ожидается bottom -> [1, 2] <- top\n",
   "solution": "class Stack:\n    \"\"\"Стек (LIFO — Last In, First Out) на списке Python — так делали на парах.\n    Вершина стека — КОНЕЦ списка: append и pop в конце работают за O(1).\n    Сам стек занимает O(n).\"\"\"\n\n    def __init__(self):\n        self.data = []\n\n    def add(self, val):\n        \"\"\"Положить элемент на вершину (push).\n        Время O(1) амортизированно: list.append пишет в конец, изредка список\n        расширяется (копирование O(n)), но в среднем O(1). Память O(1).\"\"\"\n        self.data.append(val)\n\n    def remove(self):\n        \"\"\"Снять элемент с вершины и вернуть его (pop).\n        Время O(1): удаление последнего элемента ничего не сдвигает. Память O(1).\"\"\"\n        if not self.data:\n            raise IndexError(\"remove from empty stack\")\n        return self.data.pop()\n\n    def peek(self):\n        \"\"\"Посмотреть верхний элемент, не удаляя его. Время O(1), память O(1).\"\"\"\n        if not self.data:\n            raise IndexError(\"peek from empty stack\")\n        return self.data[-1]\n\n    def is_empty(self):\n        return len(self.data) == 0\n\n    def __len__(self):\n        return len(self.data)\n\n    def __str__(self):\n        return \"bottom -> \" + str(self.data) + \" <- top\"\n\n\n# ---------- Другой вариант: стек на связанном списке ----------\n\nclass Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\n\nclass LinkedStack:\n    \"\"\"Стек на связанном списке. Вершина — голова списка (head),\n    потому что добавить/удалить в начале списка можно за O(1).\n    Все операции — честные O(1) без амортизации; цена — ссылка next в каждом узле.\"\"\"\n\n    def __init__(self):\n        self.top = None\n        self.size = 0\n\n    def add(self, val):\n        \"\"\"Время O(1), память O(1) — один новый узел.\"\"\"\n        new_node = Node(val)\n        new_node.next = self.top\n        self.top = new_node\n        self.size += 1\n\n    def remove(self):\n        \"\"\"Время O(1), память O(1).\"\"\"\n        if self.top is None:\n            raise IndexError(\"remove from empty stack\")\n        val = self.top.val\n        self.top = self.top.next\n        self.size -= 1\n        return val\n\n    def peek(self):\n        \"\"\"Время O(1), память O(1).\"\"\"\n        if self.top is None:\n            raise IndexError(\"peek from empty stack\")\n        return self.top.val\n\n    def is_empty(self):\n        return self.top is None\n\n    def __len__(self):\n        return self.size\n",
   "tests": "\n@test(\"add, затем peek показывает последний\")\ndef _():\n    s = Stack(); s.add(1); s.add(2); eq(s.peek(), 2, \"peek()\"); eq(len(s), 2, \"len\")\n@test(\"remove возвращает в обратном порядке (LIFO)\")\ndef _():\n    s = Stack()\n    for x in [1, 2, 3]: s.add(x)\n    eq([s.remove(), s.remove(), s.remove()], [3, 2, 1], \"три remove()\")\n@test(\"peek не удаляет элемент\")\ndef _():\n    s = Stack(); s.add(5); s.peek(); s.peek(); eq(len(s), 1, \"len после двух peek\")\n@test(\"пустой стек: remove → IndexError\")\ndef _():\n    raises(IndexError, lambda: Stack().remove(), \"remove() на пустом\")\n@test(\"пустой стек: peek → IndexError\")\ndef _():\n    raises(IndexError, lambda: Stack().peek(), \"peek() на пустом\")\n@test(\"случайные операции против list\")\ndef _():\n    s, ref = Stack(), []\n    for _ in range(2000):\n        if ref and _r.random() < .45: eq(s.remove(), ref.pop(), \"remove()\")\n        else:\n            v = _r.randint(0, 99); s.add(v); ref.append(v)\n        if ref: eq(s.peek(), ref[-1], \"peek()\")\n"
  },
