   "starter": "class Queue:\n    \"\"\"Очередь (FIFO — First In, First Out) на списке Python — так делали на парах.\n    Добавляем в конец списка, забираем из начала (индекс 0).\n    Сама очередь занимает O(n).\"\"\"\n\n    def __init__(self):\n        self.data = []\n\n    def add(self, val):\n        \"\"\"Поставить элемент в конец очереди (enqueue).\n        Время O(1) амортизированно (list.append), память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def remove(self):\n        \"\"\"Забрать элемент из начала очереди (dequeue).\n        Время O(n): после pop(0) все остальные элементы сдвигаются на одну позицию влево.\n        Память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def peek(self):\n        \"\"\"Посмотреть первый элемент, не удаляя его. Время O(1), память O(1).\"\"\"\n        # TODO: твой код\n        pass\n\n    def is_empty(self):\n        return len(self.data) == 0\n\n    def __len__(self):\n        return len(self.data)\n\n    def __str__(self):\n        return \"front -> \" + str(self.data) + \" <- back\"\n\nif __name__ == \"__main__\":\n    # «Запустить» выполняет этот блок. «Проверить» запускает скрытые тесты.\n    q = Queue()\n    for x in [1, 2, 3]:\n        q.add(x)\n    print(q.peek())     # ожидается 1\n    print(q.remove())   # ожидается 1\n    print(q)            # ожидается front -> [2, 3] <- back\n",
   "solution": "class Queue:\n    \"\"\"Очередь (FIFO — First In, First Out) на списке Python — так делали на парах.\n    Добавляем в конец списка, забираем из начала (индекс 0).\n    Сама очередь занимает O(n).\"\"\"\n\n    def __init__(self):\n        self.data = []\n\n    def add(self, val):\n        \"\"\"Поставить элемент в конец очереди (enqueue).\n        Время O(1) амортизированно (list.append), память O(1).\"\"\"\n        self.data.append(val)\n\n    def remove(self):\n        \"\"\"Забрать элемент из начала очереди (dequeue).\n        Время O(n): после pop(0) все остальные элементы сдвигаются на одну позицию влево.\n        Память O(1).\"\"\"\n        if not self.data:\n            raise IndexError(\"remove from empty queue\")\n        return self.data.pop(0)\n\n    def peek(self):\n        \"\"\"Посмотреть первый элемент, не удаляя его. Время O(1), память O(1).\"\"\"\n        if not self.data:\n            raise IndexError(\"peek from empty queue\")\n        return self.data[0]\n\n    def is_empty(self):\n        return len(self.data) == 0\n\n    def __len__(self):\n        return len(self.data)\n\n    def __str__(self):\n        return \"front -> \" + str(self.data) + \" <- back\"\n\n\n# ---------- Другой вариант 1: очередь на связанном списке ----------\n\nclass Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\n\nclass LinkedQueue:\n    \"\"\"Очередь на связанном списке с указателями head и tail.\n    Добавляем в хвост, забираем из головы — обе операции O(1) по времени и памяти.\"\"\"\n\n    def __init__(self):\n        self.head = None   # отсюда забираем\n        self.tail = None   # сюда добавляем\n        self.size = 0\n\n    def add(self, val):\n        \"\"\"Время O(1): tail известен, не нужно идти по списку. Память O(1) — один узел.\"\"\"\n        new_node = Node(val)\n        if self.tail is None:          # очередь пустая\n            self.head = self.tail = new_node\n        else:\n            self.tail.next = new_node\n            self.tail = new_node\n        self.size += 1\n\n    def remove(self):\n        \"\"\"Время O(1): просто сдвигаем head. Память O(1).\"\"\"\n        if self.head is None:\n            raise IndexError(\"remove from empty queue\")\n        val = self.head.val\n        self.head = self.head.next\n        if self.head is None:          # забрали последний элемент\n            self.tail = None\n        self.size -= 1\n        return val\n\n    def peek(self):\n        if self.head is None:\n            raise IndexError(\"peek from empty queue\")\n        return self.head.val\n\n    def is_empty(self):\n        return self.head is None\n\n    def __len__(self):\n        return self.size\n\n\n# ---------- Другой вариант 2: очередь на collections.deque ----------\n\nfrom collections import deque\n\n\nclass DequeQueue:\n    \"\"\"Очередь на встроенном deque — так обычно пишут в реальном коде.\n    append и popleft — O(1), ничего не сдвигается.\"\"\"\n\n    def __init__(self):\n        self.data = deque()\n\n    def add(self, val):\n        self.data.append(val)\n\n    def remove(self):\n        if not self.data:\n            raise IndexError(\"remove from empty queue\")\n        return self.data.popleft()\n\n    def peek(self):\n        if not self.data:\n            raise IndexError(\"peek from empty queue\")\n        return self.data[0]\n\n    def is_empty(self):\n        return not self.data\n\n    def __len__(self):\n        return len(self.data)\n",
   "tests": "\n@test(\"peek показывает первый добавленный\")\ndef _():\n    q = Queue(); q.add(1); q.add(2); eq(q.peek(), 1, \"peek()\"); eq(len(q), 2, \"len\")\n@test(\"remove в порядке добавления (FIFO)\")\ndef _():\n    q = Queue()\n    for x in [1, 2, 3]: q.add(x)\n    eq([q.remove(), q.remove(), q.remove()], [1, 2, 3], \"три remove()\")\n@test(\"peek не удаляет элемент\")\ndef _():\n    q = Queue(); q.add(5); q.peek(); q.peek(); eq(len(q), 1, \"len после двух peek\")\n@test(\"пустая очередь: remove → IndexError\")\ndef _():\n    raises(IndexError, lambda: Queue().remove(), \"remove() на пустой\")\n@test(\"пустая очередь: peek → IndexError\")\ndef _():\n    raises(IndexError, lambda: Queue().peek(), \"peek() на пустой\")\n@test(\"случайные операции против collections.deque\")\ndef _():\n    from collections import deque\n    q, ref = Queue(), deque()\n    for _ in range(2000):\n        if ref and _r.random() < .45: eq(q.remove(), ref.popleft(), \"remove()\")\n        else:\n            v = _r.randint(0, 99); q.add(v); ref.append(v)\n        if ref: eq(q.peek(), ref[0], \"peek()\")\n"
