   "solution": "class Node:\n    def __init__(self, val):\n        self.val = val\n        self.next = None\n\n\nclass Linked_list:\n    \"\"\"Односвязный список (по коду преподавателя).\"\"\"\n\n    def __init__(self, *lst):\n        self.size = len(lst)\n        if not lst:\n            self.head = None\n            return\n        self.head = Node(lst[0])\n        cur = self.head\n        for i in range(1, len(lst)):\n            cur.next = Node(lst[i])\n            cur = cur.next\n\n    def __str__(self):\n        if not self.head:\n            return 'empty'\n        return '->'.join(str(v) for v in self)\n\n    def __len__(self):\n        return self.size\n\n    def is_empty(self):\n        return self.head is None\n\n    def _get_item(self, idx):\n        \"\"\"Вернуть УЗЕЛ по индексу. Время O(n): idx шагов от head. Память O(1).\"\"\"\n        if idx < 0 or idx >= self.size:\n            raise IndexError(\"Index out of range\")\n        cur = self.head\n        cur_idx = 0\n        while cur_idx != idx:\n            cur = cur.next\n            cur_idx += 1\n        return cur\n\n    def __getitem__(self, idx):\n        return self._get_item(idx).val\n\n    def __setitem__(self, idx, value):\n        \"\"\"lst[idx] = value. Находим узел и меняем значение.\n        Время O(n) — поиск узла, память O(1) — только указатель.\"\"\"\n        target = self._get_item(idx)\n        target.val = value\n\n    def append(self, val):\n        \"\"\"Добавить в конец. Время O(n): без указателя на хвост идём до конца.\n        Память O(1): создаём один узел.\"\"\"\n        new_node = Node(val)\n        if self.head is None:          # список пустой\n            self.head = new_node\n        else:\n            cur = self.head\n            while cur.next:            # идём до последнего узла\n                cur = cur.next\n            cur.next = new_node\n        self.size += 1\n\n    def insert(self, idx, val):\n        \"\"\"Вставить val так, чтобы он оказался на позиции idx.\n        Время O(n) на поиск prev (в начало — O(1)), память O(1) — один узел.\"\"\"\n        if idx < 0 or idx > self.size:\n            raise IndexError(\"Index out of range\")\n        new_node = Node(val)\n        if idx == 0:                   # вставка в начало — O(1)\n            new_node.next = self.head\n            self.head = new_node\n        else:\n            prev = self._get_item(idx - 1)\n            new_node.next = prev.next  # сначала цепляем хвост\n            prev.next = new_node       # потом переключаем prev\n        self.size += 1\n\n    def remove(self, val):\n        \"\"\"Удалить первое вхождение val.\n        Время O(n): в худшем случае проходим весь список. Память O(1): указатель cur.\"\"\"\n        if self.head is None:\n            raise ValueError(\"Value not found\")\n        if self.head.val == val:       # удаляем голову\n            self.head = self.head.next\n            self.size -= 1\n            return\n        cur = self.head\n        while cur.next is not None and cur.next.val != val:\n            cur = cur.next\n        if cur.next is None:\n            raise ValueError(\"Value not found\")\n        cur.next = cur.next.next       # «перепрыгиваем» удаляемый узел\n        self.size -= 1\n\n    def pop(self, idx):\n        \"\"\"Удалить элемент по индексу и вернуть его. Время O(n), память O(1).\"\"\"\n        if idx < 0 or idx >= self.size:\n            raise IndexError(\"Index out of range\")\n        if idx == 0:\n            target = self.head\n            self.head = self.head.next\n            self.size -= 1\n            return target.val\n        prev = self._get_item(idx - 1)\n        target = prev.next\n        prev.next = target.next\n        self.size -= 1\n        return target.val\n\n    def reverse(self):\n        \"\"\"Развернуть список на месте. O(n) по времени, O(1) по памяти.\"\"\"\n        prev = None\n        cur = self.head\n        while cur:\n            nxt = cur.next     # 1. запомнили следующий\n            cur.next = prev    # 2. развернули стрелку\n            prev = cur         # 3. сдвинули prev\n            cur = nxt          # 4. сдвинули cur\n        self.head = prev\n\n    def __iter__(self):\n        cur = self.head\n        while cur:\n            yield cur.val\n            cur = cur.next\n",
   "tests": "\n@test(\"разворот 4 элементов\")\ndef _():\n    l = Linked_list(1, 2, 3, 4); l.reverse(); eq(walk(l.head), [4, 3, 2, 1])\n@test(\"пустой список\")\ndef _():\n    l = Linked_list(); l.reverse(); eq(l.head, None, \"head\")\n@test(\"один элемент\")\ndef _():\n    l = Linked_list(7); l.reverse(); eq(walk(l.head), [7])\n@test(\"двойной разворот возвращает исходный список\")\ndef _():\n    l = Linked_list(*range(20)); l.reverse(); l.reverse(); eq(walk(l.head), list(range(20)))\n@test(\"len не меняется\")\ndef _():\n    l = Linked_list(1, 2, 3); l.reverse(); eq(len(l), 3, \"len\")\n"
