   "starter": "class MinStack:\n    def __init__(self):\n        # твой код\n        pass\n\n    def push(self, val: int) -> None:\n        pass\n\n    def pop(self) -> None:\n        pass\n\n    def top(self) -> int:\n        pass\n\n    def getMin(self) -> int:\n        pass\n\nif __name__ == \"__main__\":\n    # «Запустить» выполняет этот блок. «Проверить» запускает скрытые тесты.\n    s = MinStack()\n    s.push(-2); s.push(0); s.push(-3)\n    print(s.getMin())   # ожидается -3\n    s.pop()\n    print(s.top(), s.getMin())   # ожидается 0 -2\n",
   "solution": "# Время O(1) на каждую операцию.\n# Память O(n): два стека по n элементов.\n\nclass MinStack:\n    def __init__(self):\n        self.stack = []\n        self.mins = []                 # mins[i] — минимум среди stack[0..i]\n\n    def push(self, val: int) -> None:\n        self.stack.append(val)\n        self.mins.append(val if not self.mins else min(val, self.mins[-1]))\n\n    def pop(self) -> None:\n        self.stack.pop()\n        self.mins.pop()\n\n    def top(self) -> int:\n        return self.stack[-1]\n\n    def getMin(self) -> int:\n        return self.mins[-1]           # O(1)\n",
   "tests": "\n@test(\"пример из условия\")\ndef _():\n    s = MinStack(); s.push(-2); s.push(0); s.push(-3)\n    eq(s.getMin(), -3, \"getMin()\"); s.pop(); eq(s.top(), 0, \"top()\"); eq(s.getMin(), -2, \"getMin()\")\n@test(\"повторяющийся минимум\")\ndef _():\n    s = MinStack(); s.push(1); s.push(1); s.pop(); eq(s.getMin(), 1, \"getMin()\")\n@test(\"случайные операции\")\ndef _():\n    s, ref = MinStack(), []\n    for _ in range(2000):\n        if ref and _r.random() < .4: s.pop(); ref.pop()\n        else:\n            v = _r.randint(-100, 100); s.push(v); ref.append(v)\n        if ref: eq(s.getMin(), min(ref), \"getMin()\"); eq(s.top(), ref[-1], \"top()\")\n"
