   "starter": "from collections import deque\n\n\nclass MyStack:\n    \"\"\"Можно использовать только операции очереди: append, popleft, q[0], len.\"\"\"\n\n    def __init__(self):\n        self.q = deque()\n\n    def push(self, x: int) -> None:\n        # твой код\n        pass\n\n    def pop(self) -> int:\n        pass\n\n    def top(self) -> int:\n        pass\n\n    def empty(self) -> bool:\n        pass\n\nif __name__ == \"__main__\":\n    # «Запустить» выполняет этот блок. «Проверить» запускает скрытые тесты.\n    s = MyStack()\n    s.push(1); s.push(2)\n    print(s.top(), s.pop(), s.empty())   # ожидается 2 2 False\n",
   "solution": "# Время: push O(n) (прокрутка очереди), pop/top/empty O(1).\n# Память O(n): одна очередь.\n\nfrom collections import deque\n\n\nclass MyStack:\n    def __init__(self):\n        self.q = deque()               # используем только append и popleft — как очередь\n\n    def push(self, x: int) -> None:\n        self.q.append(x)\n        # прокручиваем очередь, чтобы новый элемент оказался в начале\n        for _ in range(len(self.q) - 1):\n            self.q.append(self.q.popleft())\n\n    def pop(self) -> int:\n        return self.q.popleft()\n\n    def top(self) -> int:\n        return self.q[0]\n\n    def empty(self) -> bool:\n        return not self.q\n",
   "tests": "\n@test(\"пример из условия\")\ndef _():\n    s = MyStack(); s.push(1); s.push(2)\n    eq(s.top(), 2, \"top()\"); eq(s.pop(), 2, \"pop()\"); eq(s.empty(), False, \"empty()\")\n@test(\"опустошение\")\ndef _():\n    s = MyStack(); s.push(1); s.pop(); eq(s.empty(), True, \"empty()\")\n@test(\"случайные операции (LIFO)\")\ndef _():\n    s, ref = MyStack(), []\n    for _ in range(500):\n        if ref and _r.random() < .45: eq(s.pop(), ref.pop(), \"pop()\")\n        else:\n            v = _r.randint(0, 99); s.push(v); ref.append(v)\n        if ref: eq(s.top(), ref[-1], \"top()\")\n        eq(s.empty(), not ref, \"empty()\")\n"
